import { Injectable, signal, computed, inject } from '@angular/core';
import { WebsocketService } from './websocket.service';
import { 
  SREUpdate, 
  SRETuningParams, 
  EvidenceChain, 
  EvidenceEntry 
} from '@packages/contracts';

@Injectable({
  providedIn: 'root'
})
export class SreDataService {
  public ws = inject(WebsocketService);
  
  // Master Signal for SRE State
  private state = signal<SREUpdate | null>(null);

  // Forensic Evidence Signals
  public evidenceChain = signal<EvidenceChain | null>(null);
  public activeReplayEntryId = signal<string | null>(null);
  public governanceContext = signal<{
    epoch: string;
    quorum: string;
    notary: string;
    authorityHealth: number;
  } | null>(null);

  // Derived Signals for Components
  public intent = computed(() => this.state()?.intent);
  public perception = computed(() => this.state()?.perception);
  public operationalControl = computed(() => this.state()?.operationalControl);
  public observers = computed(() => this.state()?.observers || []);
  public events = computed(() => this.state()?.events || []);
  public lastAction = computed(() => this.state()?.lastAction);
  public zTrend = signal<'UP' | 'DOWN' | 'STABLE'>('STABLE');
  public validation = computed(() => (this.state() as any)?.validation);
  public elite = computed(() => (this.state() as any)?.elite);
  public soak = computed(() => (this.state() as any)?.soak);
  public audit = computed(() => (this.state() as any)?.audit || []);
  public stability = computed(() => this.state()?.stability);
  public topology = computed(() => this.state()?.topology || { nodes: [], edges: [] });
  
  /**
   * Evidence Chain Linkage
   */
  public evidenceChainId = computed(() => this.state()?.evidenceChainId);

  private lastZScore = 0;

  public healthStatus = computed(() => {
    const p = this.perception();
    if (!p || (p.anomalyHypothesis?.support || 0) < 10) return 'INITIALIZING';
    const z = p.anomalyHypothesis.zScore;
    if (z >= 4) return 'CRITICAL';
    if (z >= 2) return 'DEGRADED';
    return 'HEALTHY';
  });

  public confidenceLevel = computed(() => {
    const p = this.perception();
    const support = p?.anomalyHypothesis?.support || 0;
    if (support < 10) return 'LOW';
    if (support < 30) return 'MEDIUM';
    return 'HIGH';
  });

  public systemStability = computed(() => {
    const s = this.stability();
    const p = this.perception();
    const c = this.operationalControl();
    
    if (!p || !c || !s || (p.anomalyHypothesis?.support || 0) < 10) return 'INITIALIZING';
    if (c.mode === 'HALTED' || p.signalIntegrityState === 'CRITICAL') return 'UNSTABLE';
    
    if (s.score < 0.4) return 'LOW';
    if (s.score < 0.7) return 'GUARDED';
    
    return 'HIGH';
  });

  public stabilityScore = computed(() => this.stability()?.score || 0);
  public stabilityBreakdown = computed(() => this.stability()?.breakdown);

  public stabilityConfidence = computed(() => {
    const p = this.perception();
    const stability = this.systemStability();

    if (!p || stability === 'INITIALIZING' || stability === 'UNSTABLE') return 0;

    const base = 1 - Math.min(p.tuningVelocity * 5, 0.5);
    const decayBonus = p.velocityDecay < 0 ? 0.2 : 0;
    return Math.min(base + decayBonus, 1.0);
  });

  public rankedBlockers = computed(() => {
    const c = this.operationalControl();
    if (!c || c.mode !== 'STABLE') return [];
    
    const decomp = (c as any).reasoningDecomposition;
    const blockers = [
      { reason: 'QUORUM_GAP', impact: 1 - decomp.quorumContribution },
      { reason: 'DIVERSITY_GAP', impact: Math.max(0, 1 - decomp.diversityFactor) },
      { reason: 'SAFETY_BUFFER', impact: decomp.safetyBuffer }
    ];
    
    return blockers.sort((a, b) => b.impact - a.impact).filter(b => b.impact > 0.05);
  });

  public nextActionEta = computed(() => {
    const c = this.operationalControl();
    if (!c || c.mode !== 'HEALING') return null;
    return Math.max(0, (c.holdTimeMs || 0) / 1000);
  });

  constructor() {
    this.connectToSreTelemetry();
    this.connectToSreAnalytics();
  }

  private lastSequenceId = -1;
  private disorderCount = 0;

  private connectToSreTelemetry() {
    this.ws.emit('sre:subscribe', {});

    this.ws.onEvent<SREUpdate>('sre:update').subscribe(update => {
      if (update.sequenceId > this.lastSequenceId + 5 && this.lastSequenceId !== -1) {
        console.warn('[SRE] Significant sequence gap detected. Requesting full sync...', 
          { missed: update.sequenceId - this.lastSequenceId });
        this.requestFullSync();
        return;
      }

      if (update.sequenceId > this.lastSequenceId) {
        this.lastSequenceId = update.sequenceId;
        
        const current = this.state();
        if (current) {
          this.state.set({
            ...current,
            ...update,
            perception: { ...current.perception, ...(update.perception || {}) },
            operationalControl: { ...current.operationalControl, ...(update.operationalControl || {}) },
            stability: { ...current.stability, ...(update.stability || {}) },
            validation: { ...((current as any).validation || {}), ...(update as any).validation },
            elite: { ...((current as any).elite || {}), ...(update as any).elite },
            business: { ...((current as any).business || {}), ...(update as any).business },
            topology: update.topology || (current as any).topology
          } as SREUpdate);
        } else {
          this.state.set(update);
        }

        const newState = this.state();
        const currentZ = newState?.perception?.anomalyHypothesis?.zScore || 0;
        if (Math.abs(currentZ - this.lastZScore) > 0.05) {
          this.zTrend.set(currentZ > this.lastZScore ? 'UP' : 'DOWN');
        } else {
          this.zTrend.set('STABLE');
        }
        this.lastZScore = currentZ;
      } else {
        this.disorderCount++;
        this.ws.emit('sre:network_disorder', { 
          sequenceId: update.sequenceId, 
          lastSequenceId: this.lastSequenceId,
          totalDisordered: this.disorderCount 
        });
      }
    });

    this.ws.onEvent<{ message: string }>('sre:error').subscribe(err => {
      console.error('[SRE] Tuning Error:', err.message);
    });

    this.ws.reconnected$.subscribe(() => {
      this.lastSequenceId = -1;
      this.ws.emit('sre:subscribe', {});
    });
  }

  private connectToSreAnalytics() {
    this.ws.emit('sre:analytics:subscribe', {});
    this.ws.reconnected$.subscribe(() => {
      this.ws.emit('sre:analytics:subscribe', {});
    });
  }

  public getAnalyticsStream() {
    return this.ws.onEvent<any>('sre:analytics:event');
  }

  public getAnalyticsInit() {
    return this.ws.onEvent<any[]>('sre:analytics:init');
  }

  private requestFullSync() {
    this.ws.emit('sre:request_full_sync', {});
    this.lastSequenceId = -1;
  }

  public tune(params: Partial<SRETuningParams>) {
    const action = { ...params, operatorTimestamp: Date.now() };
    this.ws.emit('sre:tune', action);
  }

  public injectSignal(signal: any) {
    this.ws.emit('sre:inject_signal', signal);
  }

  public injectChaos(scenario: string, nodeId: string = 'api-service') {
    this.ws.emit('sre:chaos_inject', { scenario, nodeId });
  }

  public clearChaos() {
    this.ws.emit('sre:chaos_clear', {});
  }

  public resetValidation() {
    this.ws.emit('sre:validation_reset', {});
  }

  public startSoak() {
    this.ws.emit('sre:soak_start', {});
  }

  public stopSoak() {
    this.ws.emit('sre:soak_stop', {});
  }

  public approveRequest(requestId: string, rationale: string) {
    this.ws.emit('sre:approve', { requestId, rationale });
  }

  public rejectRequest(requestId: string, rationale: string) {
    this.ws.emit('sre:reject', { requestId, rationale });
  }

  /**
   * REPLAY EXPLORER: Forensic Data Retrieval
   */
  public loadEvidenceChain(incidentId: string) {
    console.info('[SRE-FRONTEND] Requesting forensic evidence chain', { incidentId });
    this.ws.emit('sre:archaeology:load_chain', { incidentId });
    
    this.ws.onEvent<EvidenceChain>('sre:archaeology:chain_loaded').subscribe(chain => {
      this.evidenceChain.set(chain);
      if (chain.governanceContext) {
        this.governanceContext.set({
          epoch: chain.governanceContext.id,
          quorum: chain.governanceContext.quorum,
          notary: chain.governanceContext.notaryAnchor,
          authorityHealth: 1.0 // Initializing at 100%
        });
      }
      if (chain.verificationState === 'untrusted') {
        console.error('[SRE-FORENSICS] Warning: Loaded evidence chain failed integrity verification.');
      }
    });
  }

  public setReplayEntry(entryId: string) {
    this.activeReplayEntryId.set(entryId);
  }
}

import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { BehaviorSubject, firstValueFrom, timer, of } from 'rxjs';
import { switchMap, map, catchError, retry, exhaustMap } from 'rxjs/operators';
import { environment } from '../../../environments/environment';

export interface SystemEvent {
  timestamp: number;
  type: 'INFO' | 'WARNING' | 'ERROR' | 'SUCCESS' | 'INCIDENT';
  message: string;
}

export interface SystemMetrics {
  errorRate: number;
  avgLatency: number;
  activeWorkers: number;
  totalWorkers: number;
  queueDepth: number;
  mode: string;
  confidence: number;
  infrastructure?: {
    database: { status: string };
    redis: { status: string };
  };
  globalTopology?: {
    regions: Array<{
      id: string;
      status: 'HEALTHY' | 'DEGRADED' | 'FAILING' | 'OFFLINE';
      latency: number;
      load: number;
    }>;
    primaryRegion: string;
  };
  intelligence?: {
    lastAnomaly?: {
      reason: string;
      confidence: number;
      message: string;
      timestamp: number;
    } | null;
    activePolicies: string[];
    rootCause?: string;
    goal?: { id: string, target: string, priority: string };
    plan?: { goalId: string, steps: any[], estimatedTime: number };
    swarm?: {
      proposals: any[];
      winner: any;
    };
    evolution?: {
      cycle: number;
      winRate: number;
      score: number;
    };
  };
  log?: SystemEvent[];
  activeIncident?: Incident | null;
  events?: { streamLength: number, pelSize: number, dlqSize: number, latencyMs: number };
}

export interface Incident {
  id: string;
  startTime: number;
  severity: 'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL';
  description: string;
  metrics: {
    errorRate: number;
    latency: number;
  };
  cause?: string;
  postMortem?: {
    executiveSummary: string;
    causalAnalysis: { identifiedRootCause: string, evidence: string };
    strategicReasoning: { goal: string, liftOverBaseline: string, actualReward: string };
    executionLog: Array<{ step: string, status: string, details: string }>;
  };
}

@Injectable({
  providedIn: 'root'
})
export class SystemHealthService {
  private metricsSubject = new BehaviorSubject<SystemMetrics | null>(null);
  public metrics$ = this.metricsSubject.asObservable();

  private actionStateSubject = new BehaviorSubject<Record<string, 'IDLE' | 'DISPATCHED' | 'SUCCESS' | 'ERROR'>>({});
  public actionStates$ = this.actionStateSubject.asObservable();

  public currentTime$ = timer(0, 1000).pipe(
    map(() => {
      const now = new Date();
      return now.toISOString().replace('T', ' ').split('.')[0] + ' UTC';
    })
  );

  private eventLog: SystemEvent[] = [];
  private activeIncident: Incident | null = null;
  private lastMode: string = 'NORMAL';
  
  private readonly STORAGE_KEY = 'sre_control_plane_state';
  private readonly RECOVERY_COOLDOWN = 60000; // 60s
  private recoveryStartTime: number | null = null;

  constructor(private http: HttpClient) {
    this.loadState();
    
    // Defer initial poll to prevent ExpressionChangedAfterItHasBeenCheckedError
    setTimeout(() => {
      timer(0, 2000).pipe(
        // Use exhaustMap to ensure we don't start a new poll if the previous one is still pending
        exhaustMap(() => this.http.get<any>(environment.apiUrl + '/system-health').pipe(
          map((res: any) => res.data || res),
          catchError(err => {
            console.error('Health API Error', err);
            const mode = err.status === 401 ? 'INCIDENT' : 'DOWN';
            return of({
              activeWorkers: 0,
              totalWorkers: 0,
              errorRate: 100,
              confidence: 0,
              avgLatency: 0,
              mode: mode,
              events: { streamLength: 0, pelSize: 0, dlqSize: 0, latencyMs: 0 }
            });
          })
        ))
      ).subscribe(metrics => this.processMetrics(metrics));
    }, 0);
  }

  private processMetrics(metrics: any) {
    if (!metrics) return;

    // Merge logs from API if any
    if (metrics.log && Array.isArray(metrics.log)) {
      metrics.log.forEach((entry: any) => {
        if (!this.eventLog.some(e => e.message === entry.message && Math.abs(e.timestamp - entry.timestamp) < 1000)) {
          this.eventLog.push(entry);
        }
      });
      if (this.eventLog.length > 100) this.eventLog.splice(0, this.eventLog.length - 100);
    }

    // Hysteresis Logic: RECOVERING state
    console.log(`[SRE] Mode Poll: API=${metrics.mode}, lastMode=${this.lastMode}, recoveryStartTime=${this.recoveryStartTime}`);
    
    if (this.lastMode !== 'NORMAL' && metrics.mode === 'NORMAL' && !this.recoveryStartTime) {
      this.recoveryStartTime = Date.now();
      metrics.mode = 'RECOVERING';
      this.addLog('INFO', 'System stabilized. Entering recovery cooldown period.');
      console.log('[SRE] Entering RECOVERING state');
    } else if (this.recoveryStartTime) {
      const elapsed = Date.now() - this.recoveryStartTime;
      if (elapsed < this.RECOVERY_COOLDOWN) {
        metrics.mode = 'RECOVERING';
        console.log(`[SRE] Staying in RECOVERING state (elapsed: ${Math.round(elapsed/1000)}s)`);
      } else {
        this.recoveryStartTime = null;
        this.addLog('SUCCESS', 'Recovery period complete. System returned to nominal state.');
        console.log('[SRE] Returning to NORMAL state');
      }
    }

    this.lastMode = metrics.mode;
    
    // Merge with local state - prioritize API incident if it exists, otherwise keep local (Safe-Mode)
    const processed: SystemMetrics = {
      ...metrics,
      log: [...this.eventLog].reverse(), // Newest first for UI
      activeIncident: metrics.activeIncident || this.activeIncident,
      mode: metrics.mode
    };

    // Update local activeIncident if API provides a new one or clears it
    // Inject Global Intelligence & Topology (Simulated for Demo)
    processed.globalTopology = {
      primaryRegion: 'us-east-1',
      regions: [
        { id: 'us-east-1', status: 'HEALTHY', latency: 42, load: 65 },
        { id: 'us-west-2', status: metrics.errorRate > 10 ? 'DEGRADED' : 'HEALTHY', latency: 85, load: 30 },
        { id: 'eu-central-1', status: 'HEALTHY', latency: 120, load: 15 }
      ]
    };

    processed.intelligence = {
      lastAnomaly: metrics.avgLatency > 500 ? {
        reason: 'LATENCY_DRIFT',
        confidence: 0.85,
        message: `System latency drift detected (${metrics.avgLatency}ms). Historical baseline: 200ms.`,
        timestamp: Date.now()
      } : null,
      activePolicies: [
        'Static Load Protection Policy',
        'Region Affinity Enforcement',
        'Stale Lease Recovery'
      ]
    };

    this.metricsSubject.next(processed);
    this.saveState(processed.confidence);
  }

  private loadState() {
    const saved = localStorage.getItem(this.STORAGE_KEY);
    if (saved) {
      try {
        const data = JSON.parse(saved);
        this.eventLog = data.eventLog || [];
        this.activeIncident = data.activeIncident || null;
        this.lastMode = data.lastMode || 'NORMAL';
        this.recoveryStartTime = data.recoveryStartTime || null;
        const confidence = data.confidence ?? 100;
        
        // Initialize with saved state to prevent UI blanking on reload
        this.metricsSubject.next({
          activeWorkers: 0,
          totalWorkers: 0,
          queueDepth: 0,
          avgLatency: 0,
          errorRate: 0,
          confidence,
          mode: this.lastMode,
          events: { streamLength: 0, pelSize: 0, dlqSize: 0, latencyMs: 0 },
          log: this.eventLog.slice(-50),
          activeIncident: this.activeIncident,
          infrastructure: { database: { status: 'ONLINE' }, redis: { status: 'ONLINE' } }
        });
      } catch (e) {}
    }
  }

  private saveState(confidence?: number) {
    localStorage.setItem(this.STORAGE_KEY, JSON.stringify({
      eventLog: this.eventLog,
      activeIncident: this.activeIncident,
      lastMode: this.lastMode,
      recoveryStartTime: this.recoveryStartTime,
      confidence: confidence ?? this.metricsSubject.value?.confidence ?? 100
    }));
  }

  // SRE Interventions
  async setMode(mode: string) {
    this.updateActionState('MODE', 'DISPATCHED');
    try {
      // In a real app, this would be an API call
      // await firstValueFrom(this.http.post(environment.apiUrl + '/system-health/mode', { mode }));
      this.addLog('INFO', `System mode manually updated to ${mode}`);
      this.lastMode = mode;
      this.saveState();
      this.updateActionState('MODE', 'SUCCESS');
    } catch (e) {
      this.updateActionState('MODE', 'ERROR');
    }
  }

  async forceRecovery() {
    this.updateActionState('RECOVER', 'DISPATCHED');
    try {
      this.addLog('SUCCESS', 'Manual recovery signal dispatched to fleet');
      this.recoveryStartTime = null;
      this.updateActionState('RECOVER', 'SUCCESS');
    } catch (e) {
      this.updateActionState('RECOVER', 'ERROR');
    }
  }

  async drainFleet() {
    this.updateActionState('DRAIN', 'DISPATCHED');
    this.addLog('INCIDENT', 'FLEET DRAIN INITIATED - Load shedding active');
    setTimeout(() => this.updateActionState('DRAIN', 'SUCCESS'), 2000);
  }

  async replayDlq(dryRun: boolean) {
    const key = dryRun ? 'REPLAY_DRY' : 'REPLAY';
    this.updateActionState(key, 'DISPATCHED');
    this.addLog('INFO', `DLQ Replay started (DryRun: ${dryRun})`);
    setTimeout(() => this.updateActionState(key, 'SUCCESS'), 3000);
  }

  private addLog(type: SystemEvent['type'], message: string) {
    this.eventLog.push({ timestamp: Date.now(), type, message });
    if (this.eventLog.length > 100) this.eventLog.shift();
    this.saveState();
  }

  private updateActionState(key: string, state: any) {
    const current = this.actionStateSubject.value;
    this.actionStateSubject.next({ ...current, [key]: state });
  }

  getImpactSummary(action: string): string {
    switch (action) {
      case 'DRAIN': return 'IMPACT: All active workers will finish current tasks and stop. System capacity will drop to 0.';
      case 'REPLAY': return 'IMPACT: Failed messages will be re-injected into the primary stream. May cause load spikes.';
      case 'SHIELD': return 'IMPACT: Traffic shaping will be enforced via Gateway rate-limits.';
      default: return 'IMPACT: No significant systemic risk identified.';
    }
  }

  exportIncidentReport() {
    const report = {
      timestamp: new Date().toISOString(),
      activeIncident: this.activeIncident,
      logs: this.eventLog
    };
    const blob = new Blob([JSON.stringify(report, null, 2)], { type: 'application/json' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `incident-report-${Date.now()}.json`;
    a.click();
  }
}

import { Injectable } from '@angular/core';
import { io, Socket } from 'socket.io-client';
import { environment } from '../../../environments/environment';
import { Observable, Subject, BehaviorSubject } from 'rxjs';

@Injectable({
  providedIn: 'root'
})
export class WebsocketService {
  private socket: Socket;
  private eventSubject = new Subject<any>();
  private connectionStatus = new BehaviorSubject<boolean>(false);
  public isConnected$ = this.connectionStatus.asObservable();
  public reconnected$ = new Subject<void>();
  private _lastMessageAt: number = Date.now();

  get lastMessageAt(): number {
    return this._lastMessageAt;
  }

  get isAlive(): boolean {
    // If connected but no message for 30s, consider it stalled
    return this.isConnected && (Date.now() - this._lastMessageAt < 30000);
  }

  get isConnected(): boolean {
    return this.connectionStatus.value;
  }

  constructor() {
    this.socket = io(environment.wsUrl, {
      path: '/socket.io',
      transports: ['websocket', 'polling'], // Hybrid transport for production-grade reliability
      reconnection: true,
      reconnectionAttempts: Infinity,
      reconnectionDelay: 1000,
      reconnectionDelayMax: 5000,
      randomizationFactor: 0.5 // ±50% randomized backoff jitter
    });

    this.socket.on('connect', () => {
      console.log('✅ [Websocket] Operational on:', environment.wsUrl);
      this.connectionStatus.next(true);
      this.reconnected$.next();
    });

    this.socket.on('disconnect', (reason) => {
      console.warn('❌ [Websocket] Disconnected:', reason);
      this.connectionStatus.next(false);
    });

    this.socket.on('connect_error', (err) => {
      console.error('🚨 [Websocket] Connection Error:', err.message);
      // Fallback to polling if websocket fails (only if explicitly needed, 
      // but here we stay strict for Level 5 certification)
    });

    // Handle generic events if needed
    this.socket.onAny((eventName, ...args) => {
      this._lastMessageAt = Date.now();
      this.eventSubject.next({ eventName, data: args[0] });
    });
  }

  subscribeToBuild(buildId: string) {
    this.socket.emit('subscribe', buildId);
  }

  emit(eventName: string, data: any) {
    this.socket.emit(eventName, data);
  }

  onEvent<T>(eventName: string): Observable<T> {
    return new Observable<T>(observer => {
      this.socket.on(eventName, (data: T) => {
        observer.next(data);
      });
      return () => this.socket.off(eventName);
    });
  }

  get allEvents() {
    return this.eventSubject.asObservable();
  }
}

import { Injectable } from '@angular/core';
import { ApiService } from './api.service';
import { firstValueFrom, Observable } from 'rxjs';
import { map } from 'rxjs/operators';

export interface SessionState {
  sessionId: string;
  ceremonyId: string; // Compatibility field
  masterPublicKey: string;
  threshold: number;
  participants: { nodeId: string, status: string, publicKey?: string }[];
  status: string;
  aggregatedSignature?: string;
  messageHash?: string;
  transcript?: { sequence: number, timestamp: number, nodeId: string, round: string, payloadHash: string }[];
}

export type CeremonyState = SessionState;

export interface Metrics {
  activeNodes: number;
  revokedNodes: number;
  totalSessions: number;
  totalCeremonies: number; // Compatibility field
  successRate: number;
  status: string;
}

@Injectable({
  providedIn: 'root'
})
export class ZtanService {
  constructor(private api: ApiService) {}

  private mapSession(session: SessionState | null): SessionState | null {
    if (session) {
      session.ceremonyId = session.sessionId || session.ceremonyId;
      session.sessionId = session.sessionId || session.ceremonyId;
    }
    return session;
  }

  async getActiveSession(): Promise<SessionState | null> {
    try {
      const res = await firstValueFrom(this.api.get<{ active: SessionState }>('/ztan/session/active'));
      return this.mapSession(res.active);
    } catch (e) {
      return null;
    }
  }

  async getActiveCeremony(): Promise<CeremonyState | null> {
    return this.getActiveSession();
  }

  async initSession(threshold: number, participants: string[], messageHash: string): Promise<SessionState> {
    const res = await firstValueFrom(this.api.post<SessionState>('/ztan/session/init', { threshold, participants, messageHash }));
    return this.mapSession(res)!;
  }

  async initCeremony(threshold: number, participants: string[], messageHash: string): Promise<CeremonyState> {
    return this.initSession(threshold, participants, messageHash);
  }

  async submitCommitments(msg: any): Promise<SessionState> {
