@Component({
  selector: 'sre-causal-graph',
  standalone: true,
  imports: [CommonModule],
  template: `
    <div class="causal-container">
      <div class="graph-nodes">
        <div *ngFor="let node of nodes()" 
             class="node-box" 
             [class]="node.status.toLowerCase()"
             [style.left.px]="getPosition(node.id).x"
